import './App.css';
import { BrowserRouter, Route, Routes } from 'react-router-dom';
import Navigation from './Components/Navigation/Navigation';
import Accueil from './Pages/Accueil/Accueil';
import Experiences from './Pages/Experiences/Experiences';
import Profil from './Pages/Profil/Profil';

function PageEnConstruction({ title }) {
  return (
    <main className="page-placeholder">
      <h1>{title}</h1>
      <p>Cette page sera bientôt disponible.</p>
    </main>
  );
}

function App() {
  return (
    <BrowserRouter>
      <Navigation />
      <Routes>
        <Route path="/" element={<Accueil />} />
        <Route path="/profil" element={<Profil />} />
        <Route path="/experiences" element={<Experiences />} />
        <Route path="/competences" element={<PageEnConstruction title="Compétences" />} />
        <Route path="/projets" element={<PageEnConstruction title="Projets" />} />
        <Route path="/contact" element={<PageEnConstruction title="Contact" />} />
      </Routes>
    </BrowserRouter>
  );
}

export default App;
